import { ref, getDownloadURL } from "https://www.gstatic.com/firebasejs/12.10.0/firebase-storage.js";
import { auth, db, storage } from "./firebase-config.js";
import { requirePdfAccess } from "./premium.js";
import { savePdfToHistory } from "./pdf-history.js";
import { generateFileName } from "./utils.js";
import { onAuthStateChanged } from "https://www.gstatic.com/firebasejs/12.10.0/firebase-auth.js";
import { doc, getDoc } from "https://www.gstatic.com/firebasejs/12.10.0/firebase-firestore.js";
import { ensureGlobalPinExists, requireGlobalPin } from "./security-pin.js";
import { saveModuleData, loadModuleData } from "./cloud-sync.js";

const STORAGE_KEY = "parkingModuleEasyFrais";

let currentUser = null;
let currentProfile = null;
let entries = [];
let justificatifDataUrl = "";

const moisInput = document.getElementById("moisParking");
const assistantInput = document.getElementById("assistantNomParking");
const dateInput = document.getElementById("dateParking");
const enfantInput = document.getElementById("enfantParking");
const typeInput = document.getElementById("typeParking");
const lieuInput = document.getElementById("lieuParking");
const objetInput = document.getElementById("objetParking");
const montantInput = document.getElementById("montantParking");
const justificatifInput = document.getElementById("justificatifParking");
const btnPhoto = document.getElementById("btnPhotoParking");
const nomJustificatif = document.getElementById("nomJustificatifParking");

const btnAjouter = document.getElementById("btnAjouterParking");
const btnReset = document.getElementById("btnResetParking");
const btnPdf = document.getElementById("btnPdfParking");
const btnVider = document.getElementById("btnViderParking");

const body = document.getElementById("parkingBody");
const totalLignes = document.getElementById("totalLignesParking");
const totalMontant = document.getElementById("totalMontantParking");
const toast = document.getElementById("toastParking");

function showToast(message) {
  if (!toast) return;
  toast.textContent = message;
  toast.classList.add("show");
  setTimeout(() => toast.classList.remove("show"), 2200);
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
}

function formatMoney(value) {
  return `${Number(value || 0).toFixed(2).replace(".", ",")} €`;
}

function getCurrentMonthValue() {
  const now = new Date();
  return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}`;
}

function getMonthLabel(monthValue) {
  if (!monthValue) return "";
  const [year, month] = monthValue.split("-");
  const date = new Date(Number(year), Number(month) - 1, 1);
  return date.toLocaleDateString("fr-FR", { month: "long", year: "numeric" });
}

function getFileNameMonth(monthValue) {
  return monthValue || getCurrentMonthValue();
}

async function saveModule() {

  const payload = {
    mois: moisInput?.value || "",
    assistantNom: assistantInput?.value || "",
    entries
  };

  localStorage.setItem(
    STORAGE_KEY,
    JSON.stringify(payload)
  );

  await saveModuleData(currentUser.uid, "parking", payload);
}

async function loadModule() {

  try {

    const cloud = await loadModuleData(
      currentUser.uid,
      "parking"
    );

    if (cloud?.entries) {
      entries = cloud.entries;
    } else {
      const raw = localStorage.getItem(STORAGE_KEY);

      if (raw) {
        const parsed = JSON.parse(raw);
        entries = Array.isArray(parsed?.entries)
          ? parsed.entries
          : [];
      }
    }

    if (
      cloud?.mois &&
      moisInput &&
      !moisInput.value
    ) {
      moisInput.value = cloud.mois;
    }

    if (
      cloud?.assistantNom &&
      assistantInput &&
      !assistantInput.value.trim()
    ) {
      assistantInput.value = cloud.assistantNom;
    }

  } catch (error) {

    console.error(
      "Erreur chargement parking :",
      error
    );

    try {
      const raw = localStorage.getItem(STORAGE_KEY);

      if (raw) {
        const parsed = JSON.parse(raw);

        entries = Array.isArray(parsed?.entries)
          ? parsed.entries
          : [];
      }
    } catch (e) {
      console.error(e);
    }
  }
}

function resetForm() {
  if (dateInput) dateInput.value = "";
  if (enfantInput) enfantInput.value = "";
  if (typeInput) typeInput.value = "";
  if (lieuInput) lieuInput.value = "";
  if (objetInput) objetInput.value = "";
  if (montantInput) montantInput.value = "";
  if (justificatifInput) justificatifInput.value = "";
  justificatifDataUrl = "";
  if (nomJustificatif) nomJustificatif.textContent = "";
}

function getTotal() {
  return entries.reduce((sum, item) => sum + Number(item.montant || 0), 0);
}

function renderTable() {
  if (!body) return;

  if (!entries.length) {
    body.innerHTML = `
      <tr>
        <td colspan="8" class="empty-cell">Aucune dépense enregistrée</td>
      </tr>
    `;
  } else {
    const sorted = [...entries].sort(
  (a, b) => new Date(b.date) - new Date(a.date)
);
    body.innerHTML = sorted.map((item)=> `
      <tr>
        <td>${escapeHtml(item.date || "-")}</td>
        <td>${escapeHtml(item.enfant || "-")}</td>
        <td>${escapeHtml(item.type || "-")}</td>
        <td>${escapeHtml(item.lieu || "-")}</td>
        <td>${escapeHtml(item.objet || "-")}</td>
        <td>${formatMoney(item.montant)}</td>
        <td>${item.justificatifName ? "Oui" : "-"}</td>
        <td>
          <button type="button" class="table-action-btn btn-delete-entry" data-id="${escapeHtml(String(item.id))}">
            Supprimer
          </button>
        </td>
      </tr>
    `).join("");
  }

  if (totalLignes) totalLignes.textContent = String(entries.length);
  if (totalMontant) totalMontant.textContent = formatMoney(getTotal());

  document.querySelectorAll(".btn-delete-entry").forEach((btn) => {
    btn.addEventListener("click", async () => {
      const id = Number(btn.dataset.id);
      entries = entries.filter((item) => item.id !== id);
      await saveModule();
      renderTable();
      showToast("Dépense supprimée");
    });
  });
}

function validateForm() {
  if (!dateInput?.value) {
    alert("Merci de renseigner la date.");
    return false;
  }

  if (!enfantInput?.value.trim()) {
    alert("Merci de renseigner le nom de l’enfant.");
    return false;
  }

  if (!typeInput?.value.trim()) {
    alert("Merci de choisir le type de frais.");
    return false;
  }

  if (!lieuInput?.value.trim()) {
    alert("Merci de renseigner le lieu.");
    return false;
  }

  if (!objetInput?.value.trim()) {
    alert("Merci de renseigner l’objet / description.");
    return false;
  }

  if (!montantInput?.value || Number(montantInput.value) <= 0) {
    alert("Merci de renseigner un montant valide.");
    return false;
  }

  return true;
}

async function addEntry(){
  if (!validateForm()) return;

  const entry = {
    id: Date.now() + Math.floor(Math.random() * 1000),
    date: dateInput.value,
    enfant: enfantInput.value.trim(),
    type: typeInput.value.trim(),
    lieu: lieuInput.value.trim(),
    objet: objetInput.value.trim(),
    montant: Number(montantInput.value),
    justificatifDataUrl,
    justificatifName: justificatifInput?.files?.[0]?.name || ""
  };

  entries.push(entry);
  await saveModule();
  renderTable();
  resetForm();
  showToast("Dépense ajoutée");
}

async function clearAllEntries() {
  if (!entries.length) {
    showToast("Aucune dépense à supprimer");
    return;
  }

  const ok = confirm("Voulez-vous vraiment vider toute la liste des frais de parking ?");
  if (!ok) return;

  entries = [];
  await saveModule();
  renderTable();
  showToast("Liste vidée");
}

function addEasyfraisFooter(pdf) {
  const pageCount = pdf.getNumberOfPages();

  pdf.setFont("helvetica", "italic");
  pdf.setFontSize(8);
  pdf.setTextColor(120, 120, 120);

  for (let i = 1; i <= pageCount; i++) {
    pdf.setPage(i);
    const pageHeight = pdf.internal.pageSize.getHeight();
    pdf.text("Document généré automatiquement par easyfrais.fr", 10, pageHeight - 5);
  }

  pdf.setTextColor(0, 0, 0);
}

async function convertImageDataUrlToJpeg(dataUrl, quality = 0.88) {
  const img = new Image();
  img.src = dataUrl;

  await new Promise((resolve, reject) => {
    img.onload = resolve;
    img.onerror = reject;
  });

  const canvas = document.createElement("canvas");
  canvas.width = img.naturalWidth || img.width;
  canvas.height = img.naturalHeight || img.height;

  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#ffffff";
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.drawImage(img, 0, 0);

  return {
    dataUrl: canvas.toDataURL("image/jpeg", quality),
    width: canvas.width,
    height: canvas.height
  };
}
function drawCellText(pdf, textOrLines, x, y, width, height, align = "left") {
  const lines = Array.isArray(textOrLines) ? textOrLines : [String(textOrLines)];
  
  const fontSize = pdf.getFontSize();
  const lineHeight = fontSize * 0.35;

  const totalTextHeight = lines.length * lineHeight;
  let currentY = y + (height - totalTextHeight) / 2 + 2;

  lines.forEach((line) => {
    let textX = x + 2;

    if (align === "center") {
      textX = x + width / 2;
      pdf.text(line, textX, currentY, { align: "center" });
    } else if (align === "right") {
      textX = x + width - 2;
      pdf.text(line, textX, currentY, { align: "right" });
    } else {
      pdf.text(line, textX, currentY);
    }

    currentY += lineHeight;
  });
}

function isImageDataUrl(value) {
  return typeof value === "string" && value.startsWith("data:image/");
}

function getProfileLogoData() {
  return (
    currentProfile?.logoUrl ||
    currentProfile?.logoData ||
    localStorage.getItem(`profileLogoData_${currentUser?.uid || ""}`) ||
    ""
  );
}

function getProfileSignatureData() {
  return (
    currentProfile?.signatureUrl ||
    currentProfile?.signatureData ||
    localStorage.getItem(`profileSignatureData_${currentUser?.uid || ""}`) ||
    ""
  );
}
async function drawLogo(pdf) {
  const logoData = getProfileLogoData();
  if (!logoData || !isImageDataUrl(logoData)) return;

  try {
    const convertedLogo = await convertImageDataUrlToJpeg(logoData, 0.9);

    const maxWidth = 30;
    const maxHeight = 20;

    let w = convertedLogo.width;
    let h = convertedLogo.height;

    const ratio = Math.min(maxWidth / w, maxHeight / h, 1);
    w *= ratio;
    h *= ratio;

    pdf.addImage(convertedLogo.dataUrl, "JPEG", 10, 8, w, h);
  } catch (e) {
    console.error("Erreur logo :", e);
  }
}


function formatParkingDate(value) {
  const str = String(value || "");
  return /^\d{4}-\d{2}-\d{2}$/.test(str) ? str.split("-").reverse().join("/") : str;
}

function drawParkingModel(pdf, background, items, assistant, dateCreation, signature) {
  const groups = new Map();
  for (const item of items) {
    const key = String(item.enfant || "");
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(item);
  }
  let firstPage = true;
  const rowEdges = [85, 99.5, 114.8, 130.2, 145.6, 160.9, 176.2, 191.5];
  function fillLine(text, x, y, width) {
    if (!text) return;
    pdf.setFillColor(255, 255, 255);
    pdf.rect(x, y - 4, width, 5.5, "F");
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(10);
    const size = Math.min(10, 10 * width / Math.max(width, pdf.getTextWidth(text)));
    pdf.setFontSize(size);
    pdf.text(text, x, y);
  }
  for (const group of groups.values()) {
    const rows = [];
    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(9);
    for (const item of group) {
      const detail = [item.type, item.lieu, item.objet].filter(Boolean).join(" - ");
      const lines = pdf.splitTextToSize(detail, 91);
      for (let i = 0; i < lines.length; i += 3) {
        rows.push({ item, lines: lines.slice(i, i + 3), first: i === 0 });
      }
    }
    for (let offset = 0; offset < rows.length; offset += 7) {
      if (!firstPage) pdf.addPage();
      firstPage = false;
      pdf.addImage(background, "JPEG", 0, 0, 210, 297, "parking-modele", "FAST");
      fillLine(assistant, 110, 59, 79);
      fillLine(group[0].enfant, 85, 69, 103);
      fillLine(dateCreation, 61, 199.2, 34);
      let totalCents = 0;
      rows.slice(offset, offset + 7).forEach((row, index) => {
        const top = rowEdges[index];
        const bottom = rowEdges[index + 1];
        pdf.setFontSize(9);
        const baseline = (top + bottom) / 2 + 1;
        pdf.text(row.first ? formatParkingDate(row.item.date) : "(suite)", 45, baseline, { align: "center" });
        pdf.text(row.lines, 58, baseline - (row.lines.length - 1) * 1.6, { lineHeightFactor: 1 });
        if (row.first) {
          const cents = Math.round(Number(row.item.montant) * 100);
          totalCents += cents;
          pdf.text(`${(cents / 100).toFixed(2).replace(".", ",")} €`, 187, baseline, { align: "right" });
        }
      });
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(11);
      pdf.text(`${(totalCents / 100).toFixed(2).replace(".", ",")} €`, 170, 205, { align: "center" });
      if (signature) {
        const ratio = Math.min(75 / signature.width, 30 / signature.height);
        pdf.addImage(signature.dataUrl, "JPEG", 34, 223, signature.width * ratio, signature.height * ratio);
      }
    }
  }
}


async function loadParkingPdfSignature() {
  const uid = currentUser?.uid;
  if (!uid) return null;
  const candidates = [];
  let lastError = null;
  try { candidates.push(await getDownloadURL(ref(storage, `users/${uid}/profileSignatureData_${uid}`))); }
  catch (error) { if (error.code !== "storage/object-not-found") lastError = error; }
  candidates.push(currentProfile?.signatureUrl, currentProfile?.signatureData, localStorage.getItem(`profileSignatureData_${uid}`));
  for (const value of new Set(candidates.filter(Boolean))) {
    try {
      let imageData = value;
      if (/^https?:\/\//i.test(value)) {
        const response = await fetch(value);
        if (!response.ok) throw new Error("Signature indisponible");
        const blob = await response.blob();
        imageData = await new Promise((resolve, reject) => {
          const reader = new FileReader(); reader.onload = () => resolve(reader.result); reader.onerror = reject; reader.readAsDataURL(blob);
        });
      }
      if (!String(imageData).startsWith("data:image/")) continue;
      const img = new Image();
      await new Promise((resolve, reject) => { img.onload = resolve; img.onerror = reject; img.src = imageData; });
      const canvas = document.createElement("canvas");
      canvas.width = img.naturalWidth; canvas.height = img.naturalHeight;
      const context = canvas.getContext("2d");
      context.fillStyle = "white"; context.fillRect(0, 0, canvas.width, canvas.height); context.drawImage(img, 0, 0);
      return { dataUrl: canvas.toDataURL("image/jpeg", 0.92), width: canvas.width, height: canvas.height };
    } catch (error) { lastError = error; }
  }
  if (lastError) throw lastError;
  return null;
}


async function generatePdf() {

  const allowed = await requirePdfAccess();
  if (!allowed) return;

  if (!entries.length) {
    alert("Ajoute au moins une dépense avant de générer le PDF.");
    return;
  }


  const { jsPDF } = window.jspdf;
  const pdf = new jsPDF("portrait", "mm", "a4");

  const moisValue = moisInput?.value || getCurrentMonthValue();
  const moisLabel = getMonthLabel(moisValue);
  const assistantNom = assistantInput?.value?.trim() || "";
  const items = entries.filter(item => {
    const value = String(item.date || "");
    const match = value.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    const month = match ? `${match[3]}-${match[2]}` : value.slice(0, 7);
    return month === moisValue;
  });
  if (!items.length) {
    alert("Aucune dépense pour le mois sélectionné.");
    return;
  }
  let signature;
  try {
    signature = await loadParkingPdfSignature();
  } catch (error) {
    console.error("Erreur signature parking :", error);
    alert("Impossible de charger votre signature. Vérifiez votre connexion puis réessayez.");
    return;
  }
  const background = "data:image/jpeg;base64,";
  drawParkingModel(pdf, background, items, assistantNom, new Date().toLocaleDateString("fr-FR"), signature);

  for (const item of items) {
    if (!item.justificatifDataUrl) continue;

    pdf.addPage();

    pdf.setFont("helvetica", "bold");
    pdf.setFontSize(14);
    pdf.text("Justificatif - Frais de parking", 105, 15, { align: "center" });

    pdf.setFont("helvetica", "normal");
    pdf.setFontSize(11);
    pdf.text(`Date : ${item.date || "-"}`, 14, 30);
    pdf.text(`Enfant : ${item.enfant || "-"}`, 14, 37);
    pdf.text(`Lieu : ${item.lieu || "-"}`, 14, 44);
    pdf.text(`Montant : ${formatMoney(item.montant)}`, 14, 51);

    try {
      const converted = await convertImageDataUrlToJpeg(item.justificatifDataUrl);
      const ratio = Math.min(180 / converted.width, 220 / converted.height);
      pdf.addImage(converted.dataUrl, "JPEG", 15, 60, converted.width * ratio, converted.height * ratio);
    } catch (e) {
      console.log("Erreur image justificatif", e);
    }
  }


const fileName = generateFileName("Frais_parking", moisValue, assistantNom);

  try {
    await savePdfToHistory(pdf, {
      nom: fileName,
      mois: moisLabel,
      type: "Frais de parking"
    });
  } catch (error) {
    console.error("Erreur historique parking :", error);
  }

  pdf.save(fileName);
  showToast("PDF généré et enregistré dans l’historique");
}

async function loadProfileParking() {
  if (!currentUser) return;

  try {
    const profileRef = doc(db, "users", currentUser.uid, "profile", "main");
    const snap = await getDoc(profileRef);
    if (!snap.exists()) return;

    const data = snap.data() || {};
    currentProfile = data;
    const profileName = String(data.fullName || "").trim();
    const children = String(data.childrenList || "")
      .split(/\n|,/)
      .map((item) => item.trim())
      .filter(Boolean);

    if (assistantInput && !assistantInput.value.trim() && profileName) {
      assistantInput.value = profileName;
      await saveModule();
    }

    const datalist = document.getElementById("profileChildrenList");
    if (datalist) {
      datalist.innerHTML = "";
      children.forEach((child) => {
        const option = document.createElement("option");
        option.value = child;
        datalist.appendChild(option);
      });
    }
  } catch (error) {
    console.error("Erreur chargement profil parking :", error);
  }
}

function bindEvents() {
  if (btnPhoto && justificatifInput) {
    btnPhoto.addEventListener("click", () => justificatifInput.click());
  }

  if (justificatifInput) {
    justificatifInput.addEventListener("change", () => {
      const file = justificatifInput.files?.[0];
      if (!file) {
        justificatifDataUrl = "";
        if (nomJustificatif) nomJustificatif.textContent = "";
        return;
      }

      if (nomJustificatif) nomJustificatif.textContent = file.name;

      const reader = new FileReader();
      reader.onload = () => {
        justificatifDataUrl = reader.result || "";
      };
      reader.readAsDataURL(file);
    });
  }

  if (btnAjouter) btnAjouter.addEventListener("click", addEntry);
  if (btnReset) btnReset.addEventListener("click", resetForm);
  if (btnPdf) btnPdf.addEventListener("click", generatePdf);
  if (btnVider) btnVider.addEventListener("click", clearAllEntries);

  if (moisInput) {
  moisInput.addEventListener("change", async () => {
    await saveModule();
  });
}

if (assistantInput) {
  assistantInput.addEventListener("input", async () => {
    await saveModule();
  });
}
}

onAuthStateChanged(auth, async (user) => {
  currentUser = user || null;

  if (!currentUser) {
    window.location.href = "connexion.html";
    return;
  }
  if (!ensureGlobalPinExists()) {
  window.location.href = "index.html";
  return;
}

const ok = await requireGlobalPin({
  title: "Accès au module parking",
  message: "Entre ton code PIN pour accéder à ce module."
});

if (!ok) {
  window.location.href = "index.html";
  return;
}

  if (moisInput && !moisInput.value) {
    moisInput.value = getCurrentMonthValue();
  }

await loadProfileParking();
await loadModule();

bindEvents();
renderTable();
});